const tc=document.createElement('canvas');tc.width=CW;tc.height=CH;const t=tc.getContext('2d');
let fs=16;t.font=`${fs}px Anton`;const w0=t.measureText('KİLİM').width;fs=Math.floor(fs*44/w0*10)/10;
t.font=`${fs}px Anton`;t.textAlign='center';t.textBaseline='alphabetic';t.fillStyle='#fff';t.setTransform(1,0,0,1.4,0,0);t.strokeStyle='#fff';t.lineWidth=.5;t.strokeText('KİLİM',32,19.2);t.fillText('KİLİM',32,19.2);
const TD=t.getImageData(0,0,CW,CH).data;
const isText=(c,r)=>TD[(r*CW+c)*4+3]>110;
const g=[];
for(let r=0;r<CH;r++){g[r]=[];for(let c=0;c<CW;c++){
  let col='blue';
  const k=Math.min(c,CW-1-c);
  const inner=c>=6&&c<CW-6;
  const rb=Math.min(r,CH-1-r);
  if(rb<6){ // top/bottom border
    col=rb==0||rb==5?'dark':rb==1||rb==4?'cream':(((c+(rb==2?0:2))%8)<4?'red':'ochre');
    // stepped zigzag
    if(rb==2||rb==3){const z=Math.abs((c%8)-4);col=(z==(rb==2?0:1)||z==(rb==2?4:3))?'cream':'red';if(rb==3&&z>=2)col='dark';}
  } else if(!inner){ // side borders
    if(k==0||k==5)col='dark';else if(k==1||k==4)col='cream';
    else{const m=(r%12)-6;const d=Math.abs(m)+Math.abs(k-2.5);col=d<=1.6?'ochre':d<=3.2?'red':'dark';}
  } else if(r>=6&&r<30){ // title field
    col='red';
    const lr=r-6;
    if(lr==0||lr==23)col='dark';
    else if(lr==1||lr==22)col='cream';
    if(isText(c,r)&&r>=8&&r<=28)col='cream';
    else if(lr>=2&&lr<=21&&(c<=7||c>=56)){col=((c+r)%4==0)?'ochre':'red';}
  } else if(r>=30&&r<34||r>=96&&r<100){ // chevron bands
    const rr=r<34?r-30:r-96;const z=Math.abs(((c+rr)%6)-3);
    col=z<=rr?'ochre':'dark';if(rr==3)col='cream';
  } else if(r>=34&&r<96){
    const dx=c-31.5,dy=r-65;const d=Math.abs(dx)+Math.abs(dy)*0.8;
    col='blue';
    // field: scattered small crosses
    if((c%8==3)&&(r%8==2))col='cream';
    if(((c%8==3)&&(Math.abs(r%8-2)==1))||((c%8==2||c%8==4)&&(r%8==2)))col='cream';
    if(d<=26){
      const di=Math.floor(d);
      col=di<=2?'cream':di<=5?'red':di<=7?'dark':di<=11?'ochre':di<=12?'dark':di<=17?'red':di<=18?'cream':di<=22?'green':di<=23?'cream':'dark';
      if(di>=13&&di<=17&&((Math.floor(dx)+Math.floor(dy))%4==0))col='ochre';
      if(di>=19&&di<=22&&((Math.floor(dx)+Math.floor(dy))%2==0))col='cream';
      if(di>=8&&di<=11&&((Math.floor(dx)+Math.floor(dy))%3==0))col='rust';
      if(di<=1)col='dark';
    }
    // ram's horns on the four tips
    const ax=Math.abs(dx),ay=Math.abs(dy);
    if(ax>=26&&ax<=31&&ay<=1)col='ochre';
    if(ax>=30&&ax<=31&&ay>=2&&ay<=7)col='ochre';
    if(ax>=27&&ax<=30&&ay==7)col='ochre';
    if(ax<=1&&ay>=26&&ay<=30)col='rust';
    // corner diamonds
    for(const [cc,rr] of [[11,41],[52,41],[11,89],[52,89]]){const e=Math.abs(c-cc)+Math.abs(r-rr);if(e<=5)col=e<=1?'cream':e<=3?'rust':'ochre';if(e==5)col='dark';}
    // small hooked motifs between
    for(const [cc,rr] of [[11,65],[52,65]]){const e=Math.abs(c-cc)+Math.abs(r-rr)*0.8;if(e<=6)col=e<=2?'cream':e<=4?'red':'ochre';if(e>6&&e<=7)col='dark';}
  } else if(r>=100&&r<114){ // row of small stepped diamonds
    const lr=r-100;const m=Math.abs(((c+0)%14)-7)+Math.abs(lr-6.5)*1.0;
    col=lr<=0||lr>=13?'dark':m<=2?'cream':m<=4?'rust':m<=6?'ochre':(lr%2?'blue':'plum');
    if(m>6.5)col='blue';
  }
  g[r][c]=col;
}}
