for(let x=0;x<1080;x+=180){o.fillStyle=(x/180)%2?'#32231a':'#281a13';o.fillRect(x,0,180,1920);o.fillStyle='#120b07';o.fillRect(x,0,3,1920);}
for(let i=0;i<260;i++){o.strokeStyle='rgba(0,0,0,.18)';o.lineWidth=1;o.beginPath();const x=R()*1080,y=R()*1920;o.moveTo(x,y);o.lineTo(x+(R()-.5)*8,y+60+R()*160);o.stroke();}
// shadow
