fr(Y0+2,-1);fr(Y0+CH*CELLH-2,1);
// wool cells
for(let r=0;r<CH;r++)for(let c=0;c<CW;c++){
  const col=g[r][c],x=X0+c*CELLW,y=Y0+r*CELLH;
  const j=1+(R()-.5)*.14;
