  o.fillStyle='rgba(255,245,220,.17)';o.fillRect(x+1,y+2,CELLW-2,2.4);
  o.fillStyle='rgba(0,0,0,.22)';o.fillRect(x,y+CELLH-3,CELLW,2.2);
  // wool fibres
  o.strokeStyle=R()<.5?'rgba(255,240,210,.22)':'rgba(0,0,0,.2)';o.lineWidth=1;
  for(let f=0;f<2;f++){const fx=x+2+R()*(CELLW-4);o.beginPath();o.moveTo(fx,y+3+R()*2);o.lineTo(fx+(R()-.3)*5,y+CELLH-4-R()*2);o.stroke();}
